161	// syncTags force-fetches every tag from the remote the current branch pulls
162	// from, and returns the local tags that now point somewhere else.
163	//
164	// It never prunes: `--prune` with a tag refspec deletes every tag the remote
165	// does not have, which is a tag someone made here and never pushed. That is
166	// also what a global `fetch.prune = true` does to this refspec, so the flag is
167	// passed explicitly rather than assumed absent.
168	//
169	// The branch fetch in Sync prunes, and `fetch.pruneTags = true` (or
170	// `remote.<name>.pruneTags`) would make that prune cover refs/tags/* too,
171	// deleting the same local-only tags this function keeps. Sync therefore passes
172	// `--no-prune-tags` there (git 2.17+, DEVDESK-135).
173	//
174	// A repository with no such remote — a local-only one, or a branch tracking
175	// "." — has no tags to follow, and that is not an error: the branch fetch
176	// after it decides what the repository's remotes allow.
177	func syncTags(repoPath, token string) ([]string, error) {
178		remote := tagRemote(repoPath)
179		if remote == "" {
180			return nil, nil
181		}
182		before, err := tagTargets(repoPath)
183		if err != nil {
184			return nil, err
185		}
186		if _, err := run(repoPath, token, "fetch", "--quiet", "--no-tags", "--no-prune", remote, "+refs/tags/*:refs/tags/*"); err != nil {
187			return nil, err
188		}
189		after, err := tagTargets(repoPath)
190		if err != nil {
191			return nil, err
192		}
193		var moved []string
194		for name, old := range before {
195			if target, ok := after[name]; ok && target != old {
196				moved = append(moved, name)
197			}
198		}
199		sort.Strings(moved)
200		return moved, nil
201	}
