203	// tagRemote is the remote a plain `git fetch` would use: the current branch's
204	// own, or `origin`. Empty when that remote does not exist.
205	func tagRemote(repoPath string) string {
206		remote := "origin"
207		if branch, err := run(repoPath, "", "symbolic-ref", "--quiet", "--short", "HEAD"); err == nil {
208			if name, err := run(repoPath, "", "config", "--get", "branch."+strings.TrimSpace(branch)+".remote"); err == nil {
209				remote = strings.TrimSpace(name)
210			}
211		}
212		out, err := run(repoPath, "", "remote")
213		if err != nil {
214			return ""
215		}
216		for _, name := range strings.Fields(out) {
217			if name == remote {
218				return remote
219			}
220		}
221		return ""
222	}
