240	// divergence counts what separates HEAD from its upstream, in both directions.
241	func divergence(repoPath string) (behind, ahead int, err error) {
242		out, err := run(repoPath, "", "rev-list", "--count", "--left-right", "@{u}...HEAD")
243		if err != nil {
244			return 0, 0, err
245		}
246		fields := strings.Fields(out)
247		if len(fields) != 2 {
248			return 0, 0, fmt.Errorf("unreadable rev-list output: %q", strings.TrimSpace(out))
249		}
250		if behind, err = strconv.Atoi(fields[0]); err != nil {
251			return 0, 0, fmt.Errorf("unreadable behind count: %w", err)
252		}
253		if ahead, err = strconv.Atoi(fields[1]); err != nil {
254			return 0, 0, fmt.Errorf("unreadable ahead count: %w", err)
255		}
256		return behind, ahead, nil
257	}
