259	// isDirty reports whether the working tree has anything uncommitted, untracked
260	// files included: a fast-forward can refuse to overwrite one, and a refusal is
261	// better reported before the merge than as git's error after it.
262	func isDirty(repoPath string) (bool, error) {
263		out, err := run(repoPath, "", "status", "--porcelain")
264		if err != nil {
265			return false, err
266		}
267		return strings.TrimSpace(out) != "", nil
268	}
