270	// run executes one git command in a repository and returns its stdout.
271	//
272	// It carries the same non-interactive environment as Clone. A `git fetch` is a
273	// network call like any other, and left to itself it reaches the credential
274	// helper — which on Windows writes to the console over the rendered frame and
275	// then waits on a browser. That was §3.16's observed failure, and nothing about
276	// it was specific to cloning.
277	func run(repoPath, token string, args ...string) (string, error) {
278		return runContext(context.Background(), repoPath, token, args...)
279	}
280	
281	// runContext is run with a context, so a long fetch can be abandoned.
282	func runContext(ctx context.Context, repoPath, token string, args ...string) (string, error) {
283		return runContextMax(ctx, repoPath, token, 0, args...)
284	}
