306	// hardening is the configuration a read-only command runs with, ahead of its
307	// own arguments: the repository is not trusted, and its .git/config or hooks
308	// must not make a read run a program of its choosing (DEVDESK-753). A -c option
309	// wins over every configuration file. /dev/null also works for git on Windows,
310	// which maps it itself.
311	//
312	// It stops the two hooks a status reaches without any user action, the file
313	// system monitor and the repository's hooks. Other settings that name a program
314	// (a filter driver, an external diff) are not covered.
315	//
316	// Only runReadOnly applies it. Sync, clone, fetch and pull go through
317	// runContextMax, which leaves the repository's hooks alone: a post-merge hook
318	// such as git-lfs's is part of what the user asked for when syncing.
319	func hardening() []string {
320		return []string{"-c", "core.fsmonitor=false", "-c", "core.hooksPath=" + os.DevNull}
321	}
322	
323	// runContextMax is runContext with a ceiling on what stdout may hold.
324	func runContextMax(ctx context.Context, repoPath, token string, max int64, args ...string) (string, error) {
325		return runGit(ctx, false, repoPath, token, max, args...)
326	}
327	
328	// runReadOnly runs a command that only reads a repository, with the hardening
329	// above and without taking the index lock: a status must not make a concurrent
330	// git of the user fail for no reason.
331	func runReadOnly(ctx context.Context, repoPath string, args ...string) (string, error) {
332		return runGit(ctx, true, repoPath, "", 0, args...)
333	}
334	
335	func runGit(ctx context.Context, readOnly bool, repoPath, token string, max int64, args ...string) (string, error) {
336		env := nonInteractiveEnv(token)
337		if readOnly {
338			args = append(hardening(), args...)
339			env = append(env, "GIT_OPTIONAL_LOCKS=0")
340		}
341		cmd := exec.CommandContext(ctx, "git", args...)
342		cmd.Dir = repoPath
343		cmd.Env = env
344	
345		stdout := &capWriter{max: max}
346		var stderr strings.Builder
347		cmd.Stdin = nil
348		cmd.Stdout = stdout
349		cmd.Stderr = &stderr
350	
351		if err := cmd.Run(); err != nil {
352			if ctx.Err() != nil {
353				return "", ctx.Err()
354			}
355			// The process may die of the broken pipe before Run reports the write
356			// error, so the flag is the reliable signal.
357			if stdout.exceeded {
358				return "", ErrOutputTooLarge
359			}
360			if reason := lastLine(stderr.String()); reason != "" {
361				return "", fmt.Errorf("%s", reason)
362			}
363			return "", err
364		}
365		return stdout.buf.String(), nil
366	}
