289	// capWriter collects output up to max bytes (no limit when max is 0) and fails
290	// the write past it, which makes the child's stdout copy fail and stops the
291	// process instead of buffering whatever it wants to say.
292	type capWriter struct {
293		buf      strings.Builder
294		max      int64
295		exceeded bool
296	}
297	
298	func (w *capWriter) Write(p []byte) (int, error) {
299		if w.max > 0 && int64(w.buf.Len()+len(p)) > w.max {
300			w.exceeded = true
301			return 0, ErrOutputTooLarge
302		}
303		return w.buf.Write(p)
304	}
