335	func runGit(ctx context.Context, readOnly bool, repoPath, token string, max int64, args ...string) (string, error) {
336		env := nonInteractiveEnv(token)
337		if readOnly {
338			args = append(hardening(), args...)
339			env = append(env, "GIT_OPTIONAL_LOCKS=0")
340		}
341		cmd := exec.CommandContext(ctx, "git", args...)
342		cmd.Dir = repoPath
343		cmd.Env = env
344	
345		stdout := &capWriter{max: max}
346		var stderr strings.Builder
347		cmd.Stdin = nil
348		cmd.Stdout = stdout
349		cmd.Stderr = &stderr
350	
351		if err := cmd.Run(); err != nil {
352			if ctx.Err() != nil {
353				return "", ctx.Err()
354			}
355			// The process may die of the broken pipe before Run reports the write
356			// error, so the flag is the reliable signal.
357			if stdout.exceeded {
358				return "", ErrOutputTooLarge
359			}
360			if reason := lastLine(stderr.String()); reason != "" {
361				return "", fmt.Errorf("%s", reason)
362			}
363			return "", err
364		}
365		return stdout.buf.String(), nil
366	}
